{
  "answerable": true,
  "decline_reason": "none",
  "sql": "WITH part AS (SELECT h.portfolio_id, SUM(h.quantity * s.current_price) AS tech_val FROM holdings h JOIN securities s ON s.security_id = h.security_id JOIN sectors sec ON sec.sector_id = s.sector_id WHERE sec.sector_name = 'Technology' GROUP BY h.portfolio_id), whole AS (SELECT h.portfolio_id, SUM(h.quantity * s.current_price) AS total_val FROM holdings h JOIN securities s ON s.security_id = h.security_id GROUP BY h.portfolio_id) SELECT p.portfolio_name, part.tech_val, whole.total_val, ROUND(part.tech_val * 100.0 / whole.total_val, 2) AS tech_percentage FROM part JOIN whole ON whole.portfolio_id = part.portfolio_id JOIN portfolios p ON p.portfolio_id = part.portfolio_id ORDER BY tech_percentage DESC",
  "explanation": "The query returns the portfolio name, total market value of Technology holdings, total portfolio market value, and the percentage of Technology holdings relative to the total portfolio value for portfolios holding Technology sector securities."
}

